<?php require '../includes/functions.php';require_role('super_admin');$pdo=db();if(isset($_GET['export'])){$rows=$pdo->query('SELECT tracking_number,title,status,created_at,expected_resolution_date,department_id FROM grievances ORDER BY created_at DESC')->fetchAll();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="grievances.csv"');$out=fopen('php://output','w');fputcsv($out,['Tracking number','Title','Status','Submitted','Expected resolution','Department ID']);foreach($rows as $r)fputcsv($out,$r);exit;}$rows=$pdo->query('SELECT DATE_FORMAT(created_at,"%Y-%m") month,COUNT(*) total,SUM(status IN ("Resolved","Closed")) resolved,SUM(status="Rejected") rejected FROM grievances GROUP BY month ORDER BY month DESC LIMIT 24')->fetchAll();$dept=$pdo->query('SELECT d.name,COUNT(g.id) total,SUM(g.status IN ("Resolved","Closed")) resolved FROM departments d LEFT JOIN grievances g ON g.department_id=d.id GROUP BY d.id ORDER BY total DESC')->fetchAll();$pageTitle='Reports';require '../includes/header.php';?><h1>Reports and analytics</h1><p><a class="button" href="<?=e(url('admin/reports.php?export=1'))?>">Export grievances CSV</a></p><section class="panel"><h2>Monthly totals</h2><table><tr><th>Month</th><th>Total</th><th>Resolved</th><th>Rejected</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['month'])?></td><td><?=$r['total']?></td><td><?=$r['resolved']?></td><td><?=$r['rejected']?></td></tr><?php endforeach?></table></section><section class="panel"><h2>By department</h2><table><tr><th>Department</th><th>Total</th><th>Resolved</th></tr><?php foreach($dept as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['total']?></td><td><?=$r['resolved']?></td></tr><?php endforeach?></table></section><?php require '../includes/footer.php';?>
